GROUPS = [
 dict(id='LEX-A2-01',title='Reorganizar uma viagem',after='A2-02',words=['delay','platform','miss','get back','pick up','return ticket'],
 situation='A tem return ticket: chegada14h, delay20min, plataforma de partida4; volta18h. B vai pick A up e espera14h10. A comunica chegada14h20, propõe14h30 na entrada e informa quando pretende get back. Depois imaginem que A perdeu o trem de volta: escrevam I missed the train e avisem B antes de combinar alternativa. Não inventem um novo horário oficial.',
 result='Chegada14h20; encontro14h30 apenas após aceitação; volta prevista18h até ocorrer o imprevisto. Platform4 é de partida. Modelo: There’s a twenty-minute delay. Can you pick me up at two thirty? I have a return ticket. Na rodada do imprevisto: I missed the return train; novo horário ainda desconhecido.',
 phon='Confirmar separadamente atraso, chegada e encontro. O parceiro restitui os três campos; não basta repetir twenty.',pitfall='Miss é perder transporte; não esquecer objeto. Pick me up mantém pronome no meio. Get back não permite adivinhar horário de retorno após perder o trem.'),
 dict(id='LEX-A2-02',title='Escolher e confirmar uma sala',after='A2-01',words=['book','available','enough','fit','quiet','reliable','budget','confirm'],
 situation='Grupo6, budget30. A: available15h–17h, seis lugares, quiet, preço28; B: quatro lugares, preço20. A organizador pergunta se todos fit na sala e se há enough seats. B recepção informa que A está disponível, mas ainda precisa confirmar. Organizador pede book A e confirmação escrita. Uma avaliação fictícia diz serviço usually reliable; incluam essa informação sem prometer que nunca falha.',
 result='Escolher A,28 dentro30, seis lugares exatos. Modelo: Can we book A? Is it available? Six people can fit. There are enough seats. We need a quiet room. It is within our budget. Please confirm it in writing. Serviço descrito como reliable, sem garantia absoluta.',
 phon='O destinatário distingue available de confirmed. Leia as duas situações em frases completas e peça que marque pendente/concluído.',pitfall='Fit descreve caber neste cenário; não significa barato. Confirmação solicitada não recebida; somar qualquer taxa adicional se informada.'),
 dict(id='LEX-A2-03',title='Negociar condições de participação',after='A2-05',words=['tired','appointment','rest','break','allowed','optional'],
 situation='A tem appointment para prática às15h e relata tired após o trabalho. Pede short rest/break entre as atividades. B tem regras: pausa permitida entre atividades; água allowed; caderno optional. A confirma horário e limites, sem pedir conselho médico. Troquem os papéis com compromisso16h e pausa somente após primeira atividade.',
 result='Appointment mantém hora combinada. Modelo: I feel tired. Could I take a short rest? A short break between activities is allowed. The notebook is optional. As expressões rest/break podem se sobrepor; respeitar a condição da pausa.',
 phon='Distinguir allowed e not allowed pela mensagem completa. O destinatário devolve o que pode fazer e quando.',pitfall='Tired não é diagnóstico. Optional não significa proibido; evitar que ajuda com língua vire recomendação clínica.'),
 dict(id='LEX-A2-04',title='Atualizar mensagem e procedimento digital',after='A2-06',words=['attachment','reply','log in','password','set up','fill in','turn off','already','yet'],
 situation='Simulação em papel: A consegue log in com cartão fictício, já preencheu formulário e enviou mensagem, mas esqueceu attachment. B responde pedindo anexo e informa que sala ainda não foi set up. A completa envio, confirma o que already foi feito e o que not yet. Após gravar uma saudação fictícia, pede turn it off para o microfone. Ninguém escreve ou envia senha real; só menciona password numa frase sobre não compartilhar.',
 result='Formulário preenchido; primeiro envio sem anexo; reenvio com anexo deve ser explicitado antes de marcar concluído. Sala ainda não preparada. Modelo: I’ve already filled in the form, but I haven’t sent the attachment yet. Please reply to my message. We need to set the room up. Turn it off. I don’t need to send my password.',
 phon='Ouça have/haven’t com apoio e registre estados por tarefa. Se só ler, marcar leitura; não fingir escuta.',pitfall='Nove alvos podem exigir dois encontros: mensagens/estados e instruções. Separar se houver sobrecarga. A simulação não opera aplicativo real.'),
 dict(id='LEX-A2-05',title='Buscar um item e conferir o comprovante',after='A2-03',words=['collect','lost','receipt'],
 situation='A deixou bolsa no café, sem ver quem a pegou. B é setor lost property e tem bolsa correspondente disponível após16h. A pode collect às17h e possui receipt de compra fictício com modelo e cor, mas sem número identificador único. Confiram também etiqueta e conteúdo descritos: azul/LEE/dois livros. Não tratar comprovante genérico como prova única de propriedade.',
 result='Item perdido, sem roubo afirmado; retirada às17h respeita após16h. Modelo: I’ve lost my bag. Can I collect it at five? I have a receipt, and I can describe the contents. Identificação usa os dados do cenário, não regra universal de segurança.',
 phon='Pedir que o ouvinte restitua hora de disponibilidade e hora escolhida. Confirmar receipt como palavra completa, sem exigir notação fonética.',pitfall='Collect neste uso é buscar; receipt não é recipe. Não solicitar documentos pessoais reais.'),
 dict(id='LEX-A2-06',title='Conversar sobre uma história',after='A2-07',words=['character','ending','interested','boring'],
 situation='Leiam microconto autoral: “Mia found a letter at the library. It had no name. She put it on the desk and waited. The door opened, but the story stops before we see who comes in.” Apoios: letter carta; desk mesa; waited esperou. A está interested em saber quem escreveu; B achou a espera boring. Discutam character e ending, atribuindo opiniões e sem inventar identidade final.',
 result='Mia é personagem; autor não identificado no microconto. Final aberto. Modelo: I’m interested in the letter. Mia is the main character. The ending is open. The waiting was boring for me. Pode discordar com base no texto; não tornar preferência fato universal.',
 phon='O ouvinte identifica se a pessoa expressa interesse ou tédio; mantenha a referência I/for me para atribuir a avaliação.',pitfall='Interested descreve quem sente interesse; boring descreve o que causa tédio. Ending não exige resolução feliz. Aceitar interpretações sinalizadas como hipóteses.'),
 dict(id='LEX-A2-07',title='Conferir a rota até uma sala',after='A2-01',words=['entrance','step-free','stairs','lift'],
 situation='A precisa chegar a sala no primeiro andar sem usar escadas. B recebe anúncio: entrance sul step-free; sala no andar superior; stairs disponíveis; lift existe, mas está fora de serviço. A pergunta sobre cada etapa da rota e registra o que precisa de alternativa confirmada. Não aceitar a frase “entrada sem degraus” como prova de acesso à sala.',
 result='Entrada sul sem degraus; acesso ao andar não confirmado por rota adequada. Modelo: Is the entrance step-free? Is the lift working? I can’t use the stairs. We need to confirm another route. O cenário não informa rota alternativa, então não inventar.',
 phon='O interlocutor restitui diferença entre entrada e trajeto interno. Repetir apenas o campo que faltou ajuda a verificar entendimento.',pitfall='Step-free não certifica acessibilidade total. A tarefa é compreensão do anúncio fictício, não laudo ou orientação técnica de obra.')
]

GROUPS += [
 dict(id='LEX-A2-08',title='Chegar a uma hospedagem e conferir a saída',after='A2-04',words=['luggage','check in','check out','single room','reception'],situation='Reserva fictícia de Ana: single room, chegada terça às 15h; check-in permitido a partir das 14h; check-out até 11h de quinta. Café da manhã não informado. Ana tem duas malas. A é hóspede e B recepção: confirmar reserva, perguntar onde deixar bagagem e se café está incluído, usando Is breakfast included? B só pode dizer que precisa verificar o café. Na segunda rodada, chegada às 13h: quarto ainda indisponível até 14h, mas local de bagagem é oferecido no cartão. Diferenciar deixar malas de registrar entrada com quarto liberado.',result='I booked a single room. Can I check in? Where can I leave my luggage? Is breakfast included? Terça 15h permite chegada após 14h; quinta 10h é saída possível antes do limite 11h. Na segunda rodada, guardar malas não garante quarto às 13h. Duas malas: two bags / two pieces of luggage, não two luggages. Café permanece sem confirmação.',phon='O destinatário distingue check IN / check OUT e at / by ao confirmar horários. Repetir data e limite separadamente; não confiar apenas na ênfase para recuperar condições.',pitfall='Condições valem só para hospedagem fictícia. Single room indica ocupação de uma pessoa; não inventar cama, café ou banheiro privativo. Retomar book/confirm/available e ticket/luggage sem contar retomadas como entradas novas.'),
 dict(id='LEX-A2-09',title='Descrever como se sente e esclarecer uma mensagem',after='A2-05',words=['headache','sore throat','feel sick','better','worse'],situation='Use personagens, não sintomas pessoais. Cartão Ana: ontem dor de cabeça; hoje não tem dor de cabeça, mas tem dor de garganta desde ontem e diz que está melhor no geral. Cartão Rui: hoje sente enjoo, ontem não; diz estar pior. A representa personagem; B recebe mensagem para encaminhar a uma recepção fictícia e pergunta Yesterday or today? / What do you mean by sick? com traduções. A pode esclarecer I feel nauseous (estou enjoado), bloco de apoio. B repete informação e pergunta se está correta, sem dar diagnóstico ou tratamento.',result='Ana: I had a headache yesterday. I don’t have one today. I’ve had a sore throat since yesterday, but I feel better. Rui: I feel sick — I feel nauseous. I feel worse than yesterday. Better não apaga dor de garganta; worse compara com ontem, não classifica gravidade. O destinatário deve conservar pessoa, sensação e tempo.',phon='O parceiro deve recuperar PRESENTE/PASSADO e better/worse em frases completas. Se repetir apenas palavra isolada, voltar ao contraste com yesterday/today. Aceitar pausas para esclarecer sentido de sick.',pitfall='Objetivo é relatar e esclarecer linguagem, não simular consulta clínica ou recomendar conduta. Não exigir autobiografia. Feel sick pode ser interpretado como enjoo ou indisposição conforme variedade/contexto; ensinar pergunta de esclarecimento evita equivalência rígida. Nauseous é apoio receptivo/produtivo opcional, não nova entrada avaliada.'),
 dict(id='LEX-A2-10',title='Pedir solução para um item ou uma reserva',after='A2-06',words=['repair','broken','exchange','delivery','cancel'],situation='Três cartões de atendimento fictício, usados em duas rodadas para evitar excesso. 1: luminária quebrada; oficina aceita analisar e prevê reparo amanhã, não concluído; entrega será combinada, não incluída automaticamente. 2: camisa vermelha recebida, cliente queria azul; loja aceita avaliar troca mediante conferência do pedido, ainda sem aceite final. 3: reserva de sala sexta; cliente pediu cancelamento, aguarda confirmação. A cliente escolhe cartão; B atendimento descreve estado e próximo passo. Depois resumam um segundo cartão para outra pessoa. Apoios: lamp = luminária; request = pedido; confirmation = confirmação; expected = previsto.',result='Can you repair this lamp? It is broken. / Can I exchange this shirt for a blue one? / I’d like to cancel my booking. Atualização: Repair is expected tomorrow. Delivery has not been arranged. The exchange request is being checked (bloco receptivo; pode usar They are checking my request). I’m waiting for cancellation confirmation. Não afirmar conserto, troca ou cancelamento executados.',phon='Destaque pedido versus resultado usando not yet e tomorrow, sem exigir passiva não ensinada. O destinatário marca Solicitação/Confirmado/Feito em português após ouvir.',pitfall='São políticas fictícias, não direitos legais universais. Atividade não envolve compra ou cancelamento real. Reformulação ativa They are checking… evita tornar passiva contínua requisito produtivo A2. Retomar receipt, collect e reply com apoio quando necessários.'),
 dict(id='LEX-A2-11',title='Escolher um programa cultural e relatar a experiência',after='A2-07',words=['exhibition','performance','audience','enjoyable','crowded'],situation='Agenda fictícia: exposição de fotografia sábado das 14h às 17h; apresentação de dança sábado às 19h, atualizada para 20h. A recebe agenda original; B recebe atualização. Combinem visita e apresentação, sem transferir mudança de horário para a exposição. Depois leiam relato: “I visited the exhibition at three. I found it enjoyable, but the room was crowded. At eight I watched the dance performance. The audience was quiet. My friend didn’t enjoy the performance.” A reconta o que o narrador gostou e o que não está informado; B verifica fatos.',result='Exposição mantém 14h–17h; apresentação passa a 20h. Narrador considera exposição enjoyable e crowded; colega não gostou da apresentação. The audience was quiet não prova opinião do público. Não atribuir ao narrador a opinião do amigo. Modelo: The exhibition was enjoyable, but crowded. The performance started at eight. My friend didn’t enjoy it; the audience was quiet.',phon='Parceiro distingue exhibition de performance pelo evento e confirma seven/eight antes de marcar agenda. Ouvinte recupera quem expressou a opinião, não apenas adjetivo positivo/negativo.',pitfall='Não confundir audience com artistas. Crowded não demonstra lotação legal excedida. Enjoyable é opinião situada; permitir preferências diferentes. Retomar character/ending/boring/interested em conversa opcional sem obrigar todos os itens no mesmo relato.')
]

GROUPS += [{'id': 'LEX-A2-12',
  'title': 'Relatar uma mudança de estado sem apagar nuances',
  'after': 'A2-07',
  'words': ['nervous', 'surprised', 'lonely', 'upset', 'calm', 'proud'],
  'situation': 'Texto autoral curto: “Yesterday Ana was nervous about her first presentation. Today the time '
               'is confirmed and she feels calm. She is surprised by a message from an old friend. She is '
               'proud of finishing the presentation, although she wants to improve it.” Segundo cartão: “Lee '
               'lives alone but does not feel lonely. Lee is upset about a cancelled visit and explains: I '
               'feel sad, not angry.” A recebe Ana, B recebe Lee; entrevistem-se com When? / About what? / '
               'Sad or angry? e montem síntese de 50–80 palavras. Troquem cartões após registrar primeira '
               'interpretação.',
  'result': 'Ana nervous ontem, calm hoje, surprised pela mensagem, proud por concluir, não por perfeição '
            'comprovada. Lee alone não lonely; upset foi esclarecido como sad, não angry. Não inferir que '
            'surpresa foi positiva só porque amigo escreveu. Modelo: Ana was nervous yesterday, but feels '
            'calm now. Lee lives alone without feeling lonely, and is sad about the cancelled visit.',
  'phon': 'Destaque YESTERDAY / NOW e ALONE / NOT LONELY. O parceiro devolve cronologia e contraste, '
          'permitindo repetição. A meta é preservar informação, não reproduzir uma emoção na voz.',
  'pitfall': 'Termos de emoção não são diagnósticos. Apoio although = embora pode ser glossado ou '
             'substituído por but. Não transformar orgulho em arrogância nem calma presente em prova de '
             'ausência de qualquer preocupação.'}]

